"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([["9547"],{8668(e,i,o){o.r(i),o.d(i,{metadata:()=>n,default:()=>u,frontMatter:()=>t,contentTitle:()=>s,toc:()=>c,assets:()=>d});var n=JSON.parse('{"id":"technical-overview/audio-drivers","title":"How do audio drivers work?","description":"This section explains how the USB connection between a fuegocable-modified audio interface and a computer\'s operating system is handled.","source":"@site/docs/technical-overview/audio-drivers.mdx","sourceDirName":"technical-overview","slug":"/technical-overview/audio-drivers","permalink":"/docs/technical-overview/audio-drivers","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":2,"frontMatter":{"sidebar_position":2},"sidebar":"tutorialSidebar","previous":{"title":"How does the mod work?","permalink":"/docs/technical-overview/how-mod-works"},"next":{"title":"Firestudio Project","permalink":"/docs/modding-guides/presonus/firestudio-project"}}'),r=o(4848),a=o(8453);let t={sidebar_position:2},s="How do audio drivers work?",d={},c=[{value:"macOS and Linux",id:"macos-and-linux",level:2},{value:"Windows",id:"windows",level:2},{value:"The ASIO Standard",id:"the-asio-standard",level:3},{value:"Open-Source Generic Driver Developed by Microsoft and Yamaha",id:"open-source-generic-driver-developed-by-microsoft-and-yamaha",level:3}];function l(e){let i={a:"a",h1:"h1",h2:"h2",h3:"h3",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(i.header,{children:(0,r.jsx)(i.h1,{id:"how-do-audio-drivers-work",children:"How do audio drivers work?"})}),"\n",(0,r.jsx)(i.p,{children:"This section explains how the USB connection between a fuegocable-modified audio interface and a computer's operating system is handled."}),"\n",(0,r.jsx)(i.h2,{id:"macos-and-linux",children:"macOS and Linux"}),"\n",(0,r.jsx)(i.p,{children:"These operating systems provide audio subsystems with enough features for professional audio software such as DAWs and effect plugins, including support for relatively low latencies."}),"\n",(0,r.jsx)(i.p,{children:"Both ALSA on Linux and Core Audio on macOS provide USB Audio Class 2.0 host support. This means that USB Audio Class-compliant interfaces can generally be used without installing a manufacturer-specific audio driver."}),"\n",(0,r.jsxs)(i.p,{children:["The XMOS chip and firmware used by fuegocable make use of the ",(0,r.jsx)(i.a,{href:"https://www.xmos.com/file/lib_xua/",children:"lib_xua"})," library, which implements a USB Audio Class 2.0-compliant audio device."]}),"\n",(0,r.jsx)(i.p,{children:"Therefore, no additional driver is required to use a fuegocable-modified interface on these operating systems because any audio software available for that systems already use the native audio subsystems (ALSA and Core Audio respectively)."}),"\n",(0,r.jsx)(i.h2,{id:"windows",children:"Windows"}),"\n",(0,r.jsx)(i.h3,{id:"the-asio-standard",children:"The ASIO Standard"}),"\n",(0,r.jsx)(i.p,{children:"In the past, Windows native audio support was not well suited to professional audio applications and low-latency operation. This is why Steinberg developed the ASIO (Audio Stream Input/Output) standard, providing a communication layer between DAWs and audio hardware that allows manufacturers to offer low-latency audio."}),"\n",(0,r.jsx)(i.p,{children:"For this reason, audio manufacturers commonly provide their own ASIO driver for Windows, and there is traditionally no single generic ASIO driver that works with every multichannel USB audio interface."}),"\n",(0,r.jsx)(i.p,{children:"Windows does have native support for USB Audio Class devices, including UAC 2.0 since Windows 10 version 1703. However, many DAWs on Windows are designed to communicate with audio hardware through ASIO, so the native Windows audio stack is not always sufficient for these applications. Some DAWs, such as REAPER, can also use other Windows audio APIs other than ASIO."}),"\n",(0,r.jsx)(i.p,{children:"The problem relevant to fuegocable is that manufacturer-specific audio drivers probably use a standard USB Audio Class implementation for the actual audio transfer while also providing additional functionality for communicating with the manufacturer's hardware but fixed for some VID and PID values, specific for their interfaces. Since these drivers are usually closed source, it is difficult to verify exactly how they actually work."}),"\n",(0,r.jsx)(i.p,{children:"Because the drivers are closed-source and digitally signed, modifying them is not a straightforward option. Using unsigned or test-signed drivers requires changing Windows security settings to disable or weaken driver-signature enforcement, which can pose a security risk to the system."}),"\n",(0,r.jsxs)(i.p,{children:["Since developing a Windows audio driver from scratch can be expensive, some audio interfaces companies use a driver from ",(0,r.jsx)(i.a,{href:"https://www.thesycon.de/eng/usb_audiodriver.shtml",children:"Thesycon"}),", rebranded and configured for the VID and PID of the particular interface."]}),"\n",(0,r.jsx)(i.p,{children:"fuegocable takes advantage of this behavior by using an existing driver instead of requiring a new one. The firmware can be configured with a specific VID and PID so that the modified interface presents itself to the operating system as another existing USB audio interface."}),"\n",(0,r.jsx)(i.p,{children:"For example, the Presonus Firestudio Project modified with fuegocable identifies itself as a Presonus AudioBox 1818VSL. The official Presonus driver therefore recognizes the device as an AudioBox 1818VSL and allows its 8 input channels and 8 output channels to be used in DAWs through ASIO over USB."}),"\n",(0,r.jsx)(i.p,{children:"For other modified interfaces, we will need to determine the most appropriate VID, PID, and driver to use. However, our tests have shown that the AudioBox 1818VSL driver works correctly with the 8 input channels, 8 output channels, and MIDI interface of the modified FireStudio Project, so any other modified interfaces could use the same values."}),"\n",(0,r.jsx)(i.h3,{id:"open-source-generic-driver-developed-by-microsoft-and-yamaha",children:"Open-Source Generic Driver Developed by Microsoft and Yamaha"}),"\n",(0,r.jsx)(i.p,{children:"Alternatively, Microsoft is developing an open-source generic USB Audio Class 2.0 driver with an ASIO interface, in collaboration with Yamaha and Qualcomm. The project is available on GitHub:"}),"\n",(0,r.jsx)(i.p,{children:(0,r.jsx)(i.a,{href:"https://github.com/microsoft/low-latency-audio",children:"https://github.com/microsoft/low-latency-audio"})}),"\n",(0,r.jsx)(i.p,{children:"The goal is to provide ASIO support for generic UAC2 devices without requiring a manufacturer-specific VID and PID."}),"\n",(0,r.jsx)(i.p,{children:"However, there is currently no public distribution of the compiled driver. This is relevant because a publicly distributed and properly signed version would allow users to install it without having to disable Windows driver-signature enforcement."})]})}function u(e={}){let{wrapper:i}={...(0,a.R)(),...e.components};return i?(0,r.jsx)(i,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}},8453(e,i,o){o.d(i,{R:()=>t,x:()=>s});var n=o(6540);let r={},a=n.createContext(r);function t(e){let i=n.useContext(a);return n.useMemo(function(){return"function"==typeof e?e(i):{...i,...e}},[i,e])}function s(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:t(e.components),n.createElement(a.Provider,{value:i},e.children)}}}]);